pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Signer maker;
    DummyERC20 base;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new Signer();
        base = new DummyERC20();
        vm.warp(1000);
    }

    function testFuzz_property(
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        duration = bound(duration, 1, 10_000 days - 1);
        expiration = bound(expiration, 1001, type(uint128).max);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20s = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721s = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(base),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20s,
            erc721Assets: erc721s
        });

        bytes memory signature = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        c.fillOrder(order, signature, floorAssetTokenIds);

        bytes32 orderHash = c.hashOrder(order);

        assertTrue(
            c.positionExpirations(uint256(orderHash)) == block.timestamp + order.duration,
            "fillOrder must record positionExpirations = fill time + duration"
        );
    }
}

